// This is just a test, and I haven't been working with GLSL (OpenGL Shading Language) for long.
// Shader by melcom (www.melcom-music.de)

#define hash(x) fract(sin(x) * 43758.5453123)

// Funktion zur Erzeugung einer Farbpalette / Function to create a color palette
vec3 pal(float t) { 
    return .5 + .5 * cos(6.28 * (1.0 * t + vec3(0.0, 0.1, 0.1))); 
}

// Hauptfunktion für das Bild / Main image function
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy * 2.0 - 1.0; // Normierung der UV-Koordinaten für den gesamten Bildschirm / Normalize UV coordinates to cover the entire screen
    uv.x *= iResolution.x / iResolution.y; // Skalierung basierend auf dem Seitenverhältnis / Scale based on aspect ratio

    float time = iTime * 1.0; // Geschwindigkeit erhöhen / Increase speed
    uv.y += sin(uv.x * 10.0 + time) * 0.1; // Animiere die Y-Koordinate / Animate the Y coordinate

    vec3 col = vec3(0.5) + 0.5 * cos(time + uv.xyx + vec3(0, 2, 4)); // Berechne die Farbe / Calculate the color

    float y = abs(uv.y);
    float sky = smoothstep(0.0, 1.0, y);
    vec3 skyColor = mix(vec3(0.004, 0.122, 0.153), vec3(0.745, 0.863, 0.965), sky); // Übergang vom Himmel / Gradient from the sky

    float mountain = smoothstep(0.5, 0.4, y - sin(uv.x * 3.0 + time) * 0.2);
    vec3 mountainColor = mix(vec3(0.094, 0.212, 0.255), vec3(0.149, 0.333, 0.404), mountain); // Übergang von den Bergen / Gradient from the mountains

    col = mix(skyColor, mountainColor, mountain); // Kombination der Farben / Combine the colors

    fragColor = vec4(col, 1.0); // Setzen der finalen Fragmentfarbe / Setting the final fragment color
}
